intro:
Returns an iterator to the first element of the chunk_view.

Let base_ denote the underlying view.

1) Available only if V models input_range. Equivalent to:
current_ = ranges::begin(base_);
remainder_ = n_;
return __outer_iterator(*this);
current_, remainder_, and n_ are underlying exposition only data members of chunk_view.

2) Available if V models forward_range. Equivalent to: return iterator<false>(this, ranges::begin(base_));, where iterator is exposition only nested class.

3) Available if V models forward_range. Equivalent to: return iterator<true>(this, ranges::begin(base_));, where iterator is exposition only nested class.

examples.code:
#include <ranges>
#include <iterator>
#include <functional>
#include <utility>
#include <cassert>
#include <iostream>

int main() {
    int values[]{3, 5, 7, 9};
    [[maybe_unused]] int nested[][2]{{1, 2}, {3, 4}};
    [[maybe_unused]] std::pair<int, int> pairs[]{{1, 10}, {2, 20}, {3, 30}};
    auto view = std::ranges::chunk_view{values, 2};
    auto position = view.begin();
    auto finish = view.end();
    assert(position != finish);
    (void)*position;
    auto copy = position;
    assert(copy == position);
    ++position;
    assert(position != copy);
    --position;
    assert(position == copy);
    position += 1;
    position -= 1;
    assert(position - copy == 0);
    assert(copy + 1 > copy);
    assert(1 + copy == copy + 1);
    (void)position[0];
    (void)std::ranges::iter_move(copy);

    assert(std::ranges::distance(view) > 0);
    std::cout << "Checks passed\n";
}
